import {
  FAKE_APP_POSITION,
  FAKE_GEOLOCATION_COUNTRY,
  FAKE_GEOLOCATION_RESPONSE,
} from '../src/constants/fake-geolocation';
import {shouldOpenGeolocationWelcomeSheet} from '../src/screens/home/home-screen/home-screen.utils';

describe('fake geolocation welcome sheet', () => {
  test('resolves an available country payload for fake mode', () => {
    expect(FAKE_GEOLOCATION_RESPONSE.status).toBe('OK');
    expect(
      FAKE_GEOLOCATION_RESPONSE.results[0].address_components[0].long_name,
    ).toBe(FAKE_GEOLOCATION_COUNTRY);
    expect(FAKE_APP_POSITION.country).toBe('China');
  });

  test('opens the home welcome sheet in fake mode even after it was shown', () => {
    expect(
      shouldOpenGeolocationWelcomeSheet(FAKE_APP_POSITION, true, true),
    ).toBe(true);
  });

  test('keeps the one-time cache rule when fake mode is off', () => {
    expect(
      shouldOpenGeolocationWelcomeSheet(FAKE_APP_POSITION, true, false),
    ).toBe(false);
    expect(
      shouldOpenGeolocationWelcomeSheet(FAKE_APP_POSITION, null, false),
    ).toBe(true);
    expect(shouldOpenGeolocationWelcomeSheet(null, null, true)).toBe(false);
  });
});

